If $\Phi$ is a Gaussian white noise, meaning that $F(d\lambda)=d\lambda$, and
$\psi$ is a Morse wavelet with
$$
\widehat{\psi}(\lambda) = \lambda^{\alpha}e^{-\lambda}1_{[0,\infty)}(\lambda),
$$
then
$ \Gamma_{11}=\Gamma_{22}= \Gamma(2\alpha+1)2^{-(2\alpha+1)}$ and
\begin{align}\notag
\Gamma_{12} =& \left(s_{1}s_{2}\right)^{\alpha+\frac{1}{2}}\int_{0}^{\infty}e^{i(t_{1}-t_{2})\lambda}\lambda^{2\alpha}e^{-(s_{1}+s_{2})\lambda}
d\lambda
\\\notag=&\Gamma(2\alpha+1)
\frac{\left(s_{1}s_{2}\right)^{\alpha+\frac{1}{2}}}{\left[(s_{1}+s_{2})-i(t_{1}-t_{2})\right]^{2\alpha+1}},
\end{align}
which implies that
\begin{align*}
\frac{\Gamma_{12}}{\sqrt{\Gamma_{11}\Gamma_{22}}} = 2^{2\alpha+1}
\frac{\left(s_{1}s_{2}\right)^{\alpha+\frac{1}{2}}}{\left[(s_{1}+s_{2})-i(t_{1}-t_{2})\right]^{2\alpha+1}}.
\end{align*}
\begin{itemize}
\item When $t_{1}=t_{2}$, $\log_{2}(s_{1})=j_{1}$,  $\log_{2}(s_{2})=j_{2}$, and $\Delta = |j_{1}-j_{2}|$,
\begin{align}\notag
\frac{|\Gamma_{12}|}{\sqrt{\Gamma_{11}\Gamma_{22}}}=&2^{2\alpha+1}
\frac{\left(s_{1}s_{2}\right)^{\alpha+\frac{1}{2}}}{(s_{1}+s_{2})^{2\alpha+1}}
=\left(\frac{2^{\Delta/2}+2^{-\Delta/2}}{2}\right)^{-(2\alpha+1)}.
\end{align}
This observation implies that the correlation between $\left|W_{\Phi}(t_{1},s_{1})\right|$ and $\left|W_{\Phi}(t_{2},s_{2})\right|$ exhibits polynomial decay with respect to the affine scale difference $|s_{1}-s_{2}|$,
or equivalently, exponential decay with respect to the logarithmic scale difference $|j_{1}-j_{2}|$.


\item When $s_{1}=s_{2}=s$,
\begin{align}\notag
\frac{|\Gamma_{12}|}{\sqrt{\Gamma_{11}\Gamma_{22}}}=&2^{2\alpha+1}
\frac{s^{2\alpha+1}}{\left|2s-i(t_{1}-t_{2})\right|^{2\alpha+1}}
=
\left[1+\left(\frac{t_{1}-t_{2}}{2s}\right)^{2}\right]^{-(\alpha+1/2)}.
\end{align}
This result indicates that
the correlation between $\left|W_{\Phi}(t_{1},s_{1})\right|$ and $\left|W_{\Phi}(t_{2},s_{2})\right|$ exhibits exponential decay with respect to the time difference $|t_{1}-t_{2}|$, with a faster decay rate at smaller scales.
\end{itemize}

